'use client';

import { useEffect, useRef, useState } from 'react';
import { Activity, ArrowDownLeft, ArrowRight, CalendarDays, Camera, Check, ChevronLeft, ChevronRight, CircleHelp, Coffee, Download, Droplets, Flame, FolderHeart, Leaf, Menu, Moon, Pencil, Plus, Search, Settings2, ShieldCheck, Sparkles, Sun, Target, Trash2, TrendingUp, Upload, Utensils, Wheat, X, Beef, LayoutDashboard, BookOpen, Globe2, Scale, Info } from 'lucide-react';
import type { Food, Goals, LocalState, Locale, Meal, MealType, Profile } from '@/lib/types';
import { foods, searchFoods } from '@/lib/foods';
import { getMealItemFood } from '@/lib/meal-items';
import { dailyNutrients, mealNutrients, foodNutrients, calculatePlan } from '@/lib/nutrition';
import { createDemoState, emptyState, loadState, saveState, sanitizeState, STORAGE_KEY } from '@/lib/storage';
import { dateKey, shiftDate, formatDate } from '@/lib/dates';
import { text, fmt, mealNames } from '@/lib/i18n';
import MealEditor from './meal-editor';
import GoalsDialog from './goals-dialog';
import { NutritionChart, WeightChart } from './charts';
import SaladArt from './salad-art';

type Tab = 'dashboard' | 'diary' | 'insights' | 'library' | 'settings';
type Confirmation = { type: 'delete'; meal: Meal } | { type: 'reset' } | { type: 'import'; data: LocalState } | null;
const tabs = [{ id: 'dashboard', en: 'Overview', ar: 'نظرة عامة', icon: LayoutDashboard }, { id: 'diary', en: 'Food diary', ar: 'يوميات الأكل', icon: Utensils }, { id: 'insights', en: 'My progress', ar: 'تقدّمي', icon: TrendingUp }, { id: 'library', en: 'Food library', ar: 'دليل الأطعمة', icon: BookOpen }, { id: 'settings', en: 'My settings', ar: 'إعداداتي', icon: Settings2 }] as const;
const mealTypes: MealType[] = ['breakfast', 'lunch', 'dinner', 'snack'];
const fieldClass = 'field';

export default function Dashboard() {
  const [state, setState] = useState<LocalState>(() => emptyState());
  const [ready, setReady] = useState(false);
  const [tab, setTab] = useState<Tab>('dashboard');
  const [date, setDate] = useState('');
  const [editor, setEditor] = useState<{ type: MealType; meal?: Meal } | null>(null);
  const [goalsOpen, setGoalsOpen] = useState(false);
  const [helpOpen, setHelpOpen] = useState(false);
  const [confirm, setConfirm] = useState<Confirmation>(null);
  const [toast, setToast] = useState('');
  const [storageError, setStorageError] = useState('');
  const [storageBlocked, setStorageBlocked] = useState(false);
  const [weightOpen, setWeightOpen] = useState(false);
  const [weightValue, setWeightValue] = useState('');
  const [weightDate, setWeightDate] = useState('');
  const [weightError, setWeightError] = useState('');
  const importRef = useRef<HTMLInputElement>(null);
  const locale = state.locale;
  const t = (en: string, ar: string) => text(locale, en, ar);

  useEffect(() => {
    const stored = loadState();
    setState(stored.state); setDate(dateKey()); setReady(true);
    if (stored.error) { setStorageError(stored.error); setStorageBlocked(true); }
  }, []);
  useEffect(() => {
    if (!ready) return;
    document.documentElement.classList.toggle('dark', state.theme === 'dark');
    document.documentElement.dir = locale === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = locale;
  }, [ready, state.theme, locale]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 4300); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => {
    function onStorage(event: StorageEvent) {
      if (event.key !== STORAGE_KEY) return;
      const result = loadState();
      if (result.error) { setStorageError(result.error); setStorageBlocked(true); return; }
      setState(result.state); setStorageError(''); setStorageBlocked(false);
    }
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, []);

  function commit(next: LocalState, success?: string, force = false) {
    if (storageBlocked && !force) {
      setState(next); setToast(t('Changes are in memory only. Repair or reset local storage to save.', 'التغييرات في الذاكرة فقط. أصلح التخزين أو أعد ضبطه للحفظ.')); return true;
    }
    const result = saveState(next);
    if (!result.ok) { setStorageError(result.error || t('Could not save on this browser.', 'تعذّر الحفظ في هذا المتصفح.')); setToast(t('Not saved. Free browser space or remove photo attachments and try again.', 'لم يتم الحفظ. وفّر مساحة أو أزل الصور وحاول مجدداً.')); return false; }
    setState(next); setStorageError(''); setStorageBlocked(false); if (success) setToast(success); return true;
  }
  function saveMeal(meal: Meal) {
    const meals = state.meals.some(item => item.id === meal.id) ? state.meals.map(item => item.id === meal.id ? meal : item) : [...state.meals, meal];
    if (commit({ ...state, meals }, t('Meal saved to this browser.', 'تم حفظ الوجبة في هذا المتصفح.'))) setEditor(null);
  }
  function saveGoals(goals: Goals, profile: Profile | null, source: 'manual' | 'calculated') {
    let weights = state.weights;
    if (profile && source === 'calculated') {
      const existing = weights.find(item => item.date === dateKey());
      const entry = { id: existing?.id || crypto.randomUUID(), date: dateKey(), weight: profile.weight };
      weights = [...weights.filter(item => item.date !== entry.date), entry];
    }
    if (commit({ ...state, goals, profile, weights, targetSource: source }, t('Your daily targets have been updated.', 'تم تحديث أهدافك اليومية.'))) setGoalsOpen(false);
  }
  function exportData(raw = false) {
    let content = JSON.stringify(state, null, 2);
    if (raw) { try { content = localStorage.getItem(STORAGE_KEY) || content; } catch { setToast(t('Browser storage is unavailable.', 'تخزين المتصفح غير متاح.')); return; } }
    const url = URL.createObjectURL(new Blob([content], { type: 'application/json' }));
    const link = document.createElement('a'); link.href = url; link.download = `a7sbha-${raw ? 'backup' : 'journal'}-${dateKey()}.json`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  async function importData(file?: File) {
    if (!file) return;
    if (file.size > 4 * 1024 * 1024) { setToast(t('Choose an exported JSON file under 4 MB.', 'اختر ملف JSON مُصدّراً بحجم أقل من 4 ميجابايت.')); return; }
    try { setConfirm({ type: 'import', data: sanitizeState(JSON.parse(await file.text())) }); } catch { setToast(t('This file is not a valid A7sbha journal. Your data is unchanged.', 'هذا الملف ليس سجلاً صالحاً من أحسبها. لم تتغير بياناتك.')); }
    if (importRef.current) importRef.current.value = '';
  }
  function confirmAction() {
    if (!confirm) return;
    let success = false;
    if (confirm.type === 'delete') success = commit({ ...state, meals: state.meals.filter(meal => meal.id !== confirm.meal.id) }, t('Meal removed.', 'تم حذف الوجبة.'));
    if (confirm.type === 'reset') success = commit({ ...emptyState(), locale, theme: state.theme }, t('Your local journal is now empty.', 'أصبح سجلّك المحلي فارغاً.'), true);
    if (confirm.type === 'import') success = commit(confirm.data, t('Journal imported successfully.', 'تم استيراد السجلّ بنجاح.'), true);
    if (success) setConfirm(null);
  }
  function logWeight(event: React.FormEvent) {
    event.preventDefault(); setWeightError('');
    const weight = Number(weightValue);
    if (!Number.isFinite(weight) || weight < 30 || weight > 350 || !weightDate || weightDate > dateKey()) { setWeightError(t('Enter a weight from 30–350 kg and a date up to today.', 'أدخل وزناً من 30 إلى 350 كجم وتاريخاً لا يتجاوز اليوم.')); return; }
    const previous = state.weights.find(item => item.date === weightDate);
    const weights = [...state.weights.filter(item => item.date !== weightDate), { id: previous?.id || crypto.randomUUID(), date: weightDate, weight }];
    let profile = state.profile, goals = state.goals;
    if (profile) {
      const newest = [...weights].sort((a, b) => b.date.localeCompare(a.date))[0]; profile = { ...profile, weight: newest.weight };
      try { if (state.targetSource === 'calculated') { const plan = calculatePlan(profile, { allowReachedGoal: true }); goals = { ...goals, calories: plan.calories, protein: plan.protein, carbs: plan.carbs, fat: plan.fat }; } } catch (e) { setWeightError((e as Error).message); return; }
    }
    if (commit({ ...state, weights, profile, goals }, t('Weight recorded. Keep going!', 'تم تسجيل وزنك. كمّل رحلتك!'))) setWeightOpen(false);
  }
  function openWeight() { setWeightValue(String(state.profile?.weight || '')); setWeightDate(dateKey()); setWeightError(''); setWeightOpen(true); }

  if (!ready) return <div className="flex min-h-screen flex-col items-center justify-center gap-4 bg-[var(--canvas)] text-[var(--green)]"><span className="flex h-16 w-16 items-center justify-center rounded-2xl bg-[var(--accent)]"><Leaf size={32} /></span><h1 className="text-2xl font-semibold">A7sbha</h1><p className="text-sm text-[var(--muted)]">Preparing your daily space…</p></div>;
  const totals = dailyNutrients(state.meals, date);
  const dayMeals = state.meals.filter(meal => meal.date === date);
  const remaining = state.goals.calories - totals.calories;
  const percent = Math.min(100, Math.max(0, totals.calories / state.goals.calories * 100));
  const water = state.water[date] || 0;
  const plan = state.profile && state.targetSource === 'calculated' ? calculatePlan(state.profile, { allowReachedGoal: true }) : null;
  const samplePresent = state.meals.some(meal => meal.id.startsWith('demo-'));
  const name = state.profile?.name || t('friend', 'صديقنا');
  const selectedTab = tabs.find(item => item.id === tab)!;
  const dateControl = <div className="flex items-center gap-1 rounded-lg border border-[var(--border)] bg-[var(--surface)] p-1 text-[var(--muted)]"><button className="icon-btn !h-7 !w-7" onClick={() => setDate(shiftDate(date, -1))} aria-label={t('Previous day', 'اليوم السابق')}><ChevronLeft size={16} className={locale === 'ar' ? 'rotate-180' : ''} /></button><CalendarDays size={14} className="hidden sm:block" /><input className="desktop-date w-[112px] bg-transparent px-1 py-1 text-[11px] text-[var(--ink)]" aria-label={t('Journal date', 'تاريخ السجل')} type="date" max={dateKey()} value={date} onChange={event => { if (event.target.value) setDate(event.target.value); }} /><button className="icon-btn !h-7 !w-7" disabled={date >= dateKey()} onClick={() => setDate(shiftDate(date, 1))} aria-label={t('Next day', 'اليوم التالي')}><ChevronRight size={16} className={locale === 'ar' ? 'rotate-180' : ''} /></button></div>;
  const openMeal = (type: MealType = 'lunch') => setEditor({ type });
  const sample = () => commit(createDemoState(state, date), t('Sample week added. Existing meal days were kept.', 'أُضيف أسبوع تجريبي مع الحفاظ على أيام وجباتك السابقة.'));
  const nutrientCards = [{ key: 'protein' as const, en: 'Protein', ar: 'البروتين', icon: Beef, color: 'var(--protein)' }, { key: 'carbs' as const, en: 'Carbs', ar: 'الكارب', icon: Wheat, color: 'var(--carbs)' }, { key: 'fat' as const, en: 'Fats', ar: 'الدهون', icon: Droplets, color: 'var(--fat)' }];

  function mealsFor(type: MealType) {
    const list = dayMeals.filter(meal => meal.type === type);
    return <section className="panel overflow-hidden" key={type}>
      <header className="flex items-center justify-between gap-3 border-b border-[var(--border)] px-5 py-4"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[var(--soft)] text-[23px]">{mealNames[type].emoji}</span><div><h3 className="text-sm font-semibold">{mealNames[type][locale]}</h3><p className="mt-1 text-[10px] text-[var(--muted)]">{list.length ? `${fmt(list.reduce((sum, meal) => sum + mealNutrients(meal).calories, 0))} ${t('kcal', 'سعرة')}` : t(mealNames[type].time, 'وقت لوجبة متوازنة')}</p></div></div><button className="icon-btn border border-[var(--border)] !text-[var(--green)]" aria-label={`${t('Add', 'إضافة')} ${mealNames[type][locale]}`} onClick={() => openMeal(type)}><Plus size={17} /></button></header>
      {list.length ? <div className="px-5">{list.map(meal => <MealRow key={meal.id} meal={meal} locale={locale} onEdit={() => setEditor({ type, meal })} onDelete={() => setConfirm({ type: 'delete', meal })} />)}</div> : <button className="flex w-full items-center justify-center gap-2 px-5 py-9 text-xs text-[var(--muted)] hover:bg-[var(--soft)]" onClick={() => openMeal(type)}><Plus size={15} />{t('Add your first meal', 'أضف وجبتك الأولى')}</button>}
    </section>;
  }

  return <div className="min-h-screen" dir={locale === 'ar' ? 'rtl' : 'ltr'}>
    <aside className="sidebar flex flex-col bg-[var(--surface)] px-5 pb-5 pt-8">
      <button className="mb-11 flex items-center gap-3 px-3 text-start" onClick={() => setTab('dashboard')} aria-label={t('A7sbha home', 'الرئيسية')}><span className="flex h-10 w-10 items-center justify-center rounded-[13px] bg-[var(--accent)] text-[var(--green)]"><Leaf size={23} /></span><span className="text-[24px] font-bold tracking-tight">{t('a7sbha', 'أحسبها')}<span className="text-[#82a763]">.</span><small className="mt-1 block text-[9px] font-normal tracking-normal text-[var(--muted)]">{t('A little balance, every day.', 'توازن صغير، كل يوم.')}</small></span></button>
      <span className="mb-4 px-4 text-[9px] font-semibold uppercase tracking-[.16em] text-[var(--muted)]">{t('Your daily space', 'مساحتك اليومية')}</span>
      <nav className="flex flex-col gap-2" aria-label={t('Main navigation', 'القائمة الرئيسية')}>{tabs.map(item => <button key={item.id} onClick={() => setTab(item.id)} aria-current={tab === item.id ? 'page' : undefined} className={`flex items-center gap-3 rounded-[10px] px-4 py-3.5 text-start text-[12px] ${tab === item.id ? 'nav-active bg-[var(--soft)] font-semibold text-[var(--green)]' : 'text-[var(--muted)] hover:bg-[var(--soft)]'}`}><item.icon size={18} />{item[locale]}</button>)}</nav>
      <div className="mt-auto rounded-2xl border border-[var(--border)] bg-[var(--soft)] px-5 py-5"><span className="mb-4 flex h-10 w-10 items-center justify-center rounded-xl bg-[var(--accent)] text-[var(--green)]"><Leaf size={23} /></span><h3 className="text-[13px] font-semibold">{t('Progress, not perfection.', 'استمرارية، مو مثالية.')}</h3><p className="mt-2 text-[11px] leading-6 text-[var(--muted)]">{t('Good habits grow one small choice at a time.', 'العادات الجيدة تكبر مع كل اختيار صغير.')}</p><button className="mt-4 flex items-center gap-2 text-[11px] font-semibold text-[var(--green)]" onClick={() => setGoalsOpen(true)}>{t('Make it personal', 'خلّها تناسبك')}<ArrowRight size={14} className={locale === 'ar' ? 'rotate-180' : ''} /></button></div>
      <button className="mt-5 flex items-center gap-3 px-3 py-3 text-[11px] text-[var(--muted)]" onClick={() => setHelpOpen(true)}><CircleHelp size={17} />{t('How it works', 'كيف يعمل الموقع؟')}</button>
      <div className="mt-2 flex items-center gap-3 border-t border-[var(--border)] px-2 pt-5"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[var(--accent)] text-sm font-semibold text-[var(--green)]">{state.profile?.name.charAt(0).toUpperCase() || <Leaf size={17} />}</span><div className="min-w-0 flex-1"><strong className="block truncate text-[11px] font-semibold">{state.profile?.name || t('Your local journal', 'سجلّك المحلي')}</strong><span className="mt-1 block text-[9px] text-[var(--muted)]">{t('Private to this browser', 'محفوظ في هذا المتصفح')}</span></div><button className="icon-btn !h-7 !w-7" onClick={() => setTab('settings')} aria-label={t('Open settings', 'فتح الإعدادات')}><Settings2 size={16} /></button></div>
    </aside>
    <div className="main-shell">
      <header className="flex h-[76px] items-center justify-between gap-3 border-b border-[var(--border)] bg-[var(--surface)]/60 px-5 sm:px-8 xl:px-10"><div className="flex items-center gap-3"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-[var(--accent)] text-[var(--green)] lg:hidden"><Leaf size={18} /></span><span className="hidden text-[11px] text-[var(--muted)] sm:inline">{t('My space', 'مساحتي')}</span><ChevronRight size={13} className="hidden text-[var(--muted)] sm:block" /><strong className="text-[12px] font-medium">{selectedTab[locale]}</strong></div><div className="flex items-center gap-2.5"><span className="me-3 hidden items-center gap-1.5 rounded-full border border-[var(--border)] bg-[var(--soft)] px-3 py-1.5 text-[9px] font-medium text-[var(--green)] sm:flex"><span className="h-1.5 w-1.5 rounded-full bg-[var(--green)]" />{t('LOCAL JOURNAL', 'تخزين محلي')}</span><button className="icon-btn" onClick={() => commit({ ...state, locale: locale === 'en' ? 'ar' : 'en' })} aria-label={t('Switch to Arabic', 'Switch to English')} title={t('العربية', 'English')}><Globe2 size={18} /><span className="sr-only">{t('العربية', 'English')}</span></button><button className="icon-btn border border-[var(--border)]" aria-label={state.theme === 'light' ? t('Switch to dark mode', 'تفعيل الوضع الداكن') : t('Switch to light mode', 'تفعيل الوضع الفاتح')} onClick={() => commit({ ...state, theme: state.theme === 'light' ? 'dark' : 'light' })}>{state.theme === 'light' ? <Moon size={17} /> : <Sun size={17} />}</button><button className="ms-1 flex h-8 w-8 items-center justify-center rounded-full bg-[var(--accent)] text-sm font-semibold text-[var(--green)]" aria-label={t('Edit daily targets', 'تعديل الأهداف اليومية')} onClick={() => setGoalsOpen(true)}>{state.profile?.name.charAt(0).toUpperCase() || 'Y'}</button></div></header>
      <main className="mx-auto max-w-[1530px] px-4 pb-28 pt-7 sm:px-8 sm:pt-8 lg:pb-6 xl:px-10">
        {storageError && <div className="mb-5 flex flex-col justify-between gap-3 rounded-xl border border-amber-300 bg-amber-50 p-4 text-xs leading-6 text-amber-900 dark:border-amber-800 dark:bg-amber-950 dark:text-amber-200" role="alert"><span><b>{t('Browser storage needs attention.', 'تخزين المتصفح يحتاج انتباهك.')}</b> {storageError} {storageBlocked ? t('Your existing stored data has been kept. New changes are in memory until you import or reset.', 'احتُفظ ببياناتك الأصلية. التغييرات الجديدة مؤقتة حتى الاستيراد أو إعادة الضبط.') : ''}</span><div className="flex flex-wrap gap-4"><button className="underline" onClick={() => exportData(true)}>{t('Download stored backup', 'تنزيل نسخة البيانات الأصلية')}</button><button className="underline" onClick={() => setConfirm({ type: 'reset' })}>{t('Reset local storage', 'إعادة ضبط التخزين')}</button></div></div>}
        <div className="mb-6 flex items-center justify-between gap-4"><div><p className="mb-2 text-[10px] font-medium uppercase tracking-[.15em] text-[var(--green)]">{t('A fresh day, a fresh start', 'يوم جديد، بداية جديدة')}</p><h1 className="text-[25px] font-semibold leading-tight sm:text-[29px]">{tab === 'dashboard' ? <>{t(`Hey ${name.split(' ')[0]}`, `هلا ${name.split(' ')[0]}`)} <span className="inline-block text-[23px]">👋</span></> : selectedTab[locale]}</h1><p className="mt-2 max-w-xl text-[11px] leading-5 text-[var(--muted)] sm:text-[12px]">{tab === 'dashboard' ? t('Let’s make today a little more balanced.', 'خلّنا نخلي يومك أكثر توازناً.') : tab === 'diary' ? t('All your meals, one thoughtful day at a time.', 'كل وجباتك، يوم بيوم.') : tab === 'library' ? t('Everyday foods. Clear portions. Arabic and English search.', 'أطعمة يومية وكميات واضحة. ابحث بالعربية والإنجليزية.') : tab === 'insights' ? t('Your habits tell a story. See how yours are growing.', 'عاداتك ترسم رحلتك. شوف كيف تتقدم.') : t('Your targets, preferences, and local data.', 'أهدافك وتفضيلاتك وبياناتك المحلية.')}</p></div>{tab === 'dashboard' || tab === 'diary' ? <button className="btn !px-3 !text-[11px] sm:!px-4 sm:!text-xs" onClick={() => openMeal()}><Plus size={17} />{t('Add meal', 'أضف وجبة')}</button> : tab === 'insights' ? <button className="btn !text-xs" onClick={openWeight}><Plus size={16} />{t('Log weight', 'سجّل وزنك')}</button> : tab === 'settings' ? <button className="btn-soft" onClick={() => setGoalsOpen(true)}><Target size={15} />{t('Edit targets', 'تعديل الأهداف')}</button> : null}</div>
        {samplePresent && <div className="mb-5 flex items-center justify-between gap-3 rounded-lg border border-[var(--border)] bg-[var(--soft)] px-4 py-2.5 text-[10px] text-[var(--muted)]"><span className="flex items-center gap-2"><Sparkles size={14} className="text-[var(--green)]" />{t('This journal includes clearly marked sample meals. You can edit or remove them.', 'السجلّ يحتوي وجبات تجريبية موضّحة. يمكنك تعديلها أو حذفها.')}</span></div>}
        {tab === 'dashboard' && <div className="reveal">
          <section className="hero-grid relative mb-6 flex min-h-[170px] items-center justify-between overflow-hidden rounded-[18px] border border-[var(--border)] px-6 py-6 sm:px-8"><div className="relative z-10 max-w-[65%]"><span className="mb-2.5 inline-flex items-center gap-1.5 rounded-full bg-[var(--surface)]/65 px-2.5 py-1 text-[9px] font-medium text-[var(--green)]"><Leaf size={12} />{t('Nourish your everyday', 'غذّ يومك بتوازن')}</span><h2 className="text-[22px] font-semibold leading-[1.25] sm:text-[27px]">{t('Small choices.', 'اختيارات صغيرة.')}<br />{t('Stronger you.', 'نسخة أقوى منك.')}</h2><p className="mt-2.5 max-w-[295px] text-[11px] leading-5 text-[var(--muted)]">{t('Know your food. Find your balance. Build habits that feel like you.', 'اعرف أكلك. لاقِ توازنك. وابنِ عادات تناسبك.')}</p></div><div className="absolute end-0 top-0 h-full w-[160px] opacity-90 sm:end-6 sm:w-[225px]"><SaladArt /></div><span className="hero-orbit -end-20 -top-36 h-[400px] w-[400px]" /><span className="hero-orbit -end-9 -top-28 h-[330px] w-[330px]" /></section>
          <div className="grid items-start gap-5 xl:grid-cols-[minmax(0,1fr)_290px]">
            <div className="min-w-0 space-y-5"><section className="panel p-5 sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><h2 className="flex items-center gap-2 text-[14px] font-semibold"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-orange-50 text-orange-400 dark:bg-orange-950/30"><Flame size={17} /></span>{t('Your daily balance', 'توازن يومك')}</h2>{dateControl}</div><div className="flex flex-col items-center justify-center gap-7 py-7 sm:flex-row sm:gap-10"><div className="relative h-[182px] w-[182px] shrink-0"><svg viewBox="0 0 200 200" className="h-full w-full" aria-hidden="true"><circle cx="100" cy="100" r="84" fill="none" stroke="var(--soft)" strokeWidth="11" /><circle className="donut-ring" cx="100" cy="100" r="84" fill="none" stroke="var(--green)" strokeWidth="11" strokeLinecap="round" strokeDasharray={`${percent / 100 * 527.79} 527.79`} /></svg><div className="absolute inset-0 flex flex-col items-center justify-center"><span className="mb-1 text-[10px] text-[var(--muted)]">{remaining >= 0 ? t('Remaining', 'باقي لك') : t('Above target', 'فوق هدفك')}</span><strong className="text-[36px] font-semibold leading-tight tracking-[-.07em] text-[var(--green)]">{fmt(Math.abs(remaining))}</strong><span className="mt-1.5 text-[10px] text-[var(--muted)]">{t('kilocalories', 'سعرة حرارية')}</span></div><span className="absolute bottom-2 end-7 flex h-8 w-8 items-center justify-center rounded-full border-[4px] border-[var(--surface)] bg-[var(--surface)] text-[var(--green)]"><Leaf size={18} /></span></div><div className="flex w-full justify-center gap-9 sm:block sm:w-auto sm:min-w-[145px]"><div className="mb-5"><span className="flex items-center gap-2 text-[10px] text-[var(--muted)]"><span className="h-1.5 w-1.5 rounded-full bg-[var(--green)]" />{t('Eaten today', 'أكلت اليوم')}</span><strong className="mt-1.5 block ps-3.5 text-[24px] font-semibold tracking-[-.04em]">{fmt(totals.calories)} <small className="text-[9px] font-normal tracking-normal text-[var(--muted)]">{t('kcal', 'سعرة')}</small></strong></div><div><span className="flex items-center gap-2 text-[10px] text-[var(--muted)]"><span className="h-1.5 w-1.5 rounded-full bg-[var(--protein)]" />{t('Daily target', 'هدفك اليومي')}</span><strong className="mt-1.5 block ps-3.5 text-[24px] font-semibold tracking-[-.04em]">{fmt(state.goals.calories)} <small className="text-[9px] font-normal tracking-normal text-[var(--muted)]">{t('kcal', 'سعرة')}</small></strong></div><button className="mt-4 hidden items-center gap-1 text-[10px] text-[var(--green)] sm:flex" onClick={() => setGoalsOpen(true)}><Pencil size={11} />{t('Personalize your targets', 'خصّص أهدافك')}</button></div></div><div className="grid grid-cols-3 gap-4 border-t border-[var(--border)] pt-5 sm:gap-6">{nutrientCards.map(nutrient => <div key={nutrient.key}><span className="flex items-center gap-1.5 text-[11px] font-medium" style={{ color: nutrient.color }}><nutrient.icon size={15} />{nutrient[locale]}</span><p className="mt-2 text-[15px] font-semibold">{fmt(totals[nutrient.key], 1)} <span className="text-[9px] font-normal text-[var(--muted)]">/ {state.goals[nutrient.key]} {t('g', 'جم')}</span></p><div className="mt-2.5 h-1.5 overflow-hidden rounded-full bg-[var(--soft)]" role="progressbar" aria-label={nutrient[locale]} aria-valuemin={0} aria-valuemax={state.goals[nutrient.key]} aria-valuenow={Math.min(totals[nutrient.key], state.goals[nutrient.key])}><span className="block h-full rounded-full transition-all" style={{ width: `${state.goals[nutrient.key] > 0 ? Math.min(100, totals[nutrient.key] / state.goals[nutrient.key] * 100) : totals[nutrient.key] > 0 ? 100 : 0}%`, background: nutrient.color }} /></div><p className="mt-2 text-[9px] text-[var(--muted)]">{totals[nutrient.key] <= state.goals[nutrient.key] ? t(`${fmt(state.goals[nutrient.key] - totals[nutrient.key], 1)} g to go`, `باقي ${fmt(state.goals[nutrient.key] - totals[nutrient.key], 1)} جم`) : t(`${fmt(totals[nutrient.key] - state.goals[nutrient.key], 1)} g above target`, `زيادة ${fmt(totals[nutrient.key] - state.goals[nutrient.key], 1)} جم`)}</p></div>)}</div></section>
              <div><div className="mb-3.5 flex items-center justify-between"><h2 className="text-[14px] font-semibold">{t('On your menu today', 'وجباتك اليوم')} <span className="ms-1 rounded-md bg-[var(--soft)] px-1.5 py-1 text-[9px] font-normal text-[var(--green)]">{dayMeals.length}</span></h2><button className="flex items-center gap-1 text-[10px] font-medium text-[var(--green)]" onClick={() => setTab('diary')}>{t('View diary', 'عرض السجلّ')}<ArrowRight size={13} className={locale === 'ar' ? 'rotate-180' : ''} /></button></div><div className="grid gap-4 sm:grid-cols-2">{mealTypes.map(mealsFor)}</div></div>
            </div>
            <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-1"><section className="relative overflow-hidden rounded-[18px] bg-[#204d39] p-6 text-[#eff5e8]"><span className="mb-5 flex w-fit items-center gap-1.5 rounded-md border border-white/10 bg-white/5 px-2 py-1 text-[9px] text-[#cadfba]"><Target size={13} />{t('YOUR PERSONAL GOAL', 'هدفك الشخصي')}</span><h2 className="text-[20px] font-semibold leading-tight">{state.profile ? state.profile.goal === 'cut' ? t('Feel lighter. Stay strong.', 'أخف وزناً، بنفس القوة.') : state.profile.goal === 'bulk' ? t('Build strength, steadily.', 'ابنِ قوتك، خطوة بخطوة.') : t('Find your everyday balance.', 'توازن يناسب كل يوم.') : t('A plan that fits you.', 'خطة تناسبك أنت.')}</h2><p className="mt-2 text-[11px] leading-5 text-[#b6caaa]">{state.profile ? t('Your body. Your pace. Your journey.', 'جسمك. سرعتك. رحلتك.') : t('Set a daily target or calculate one from your body and activity.', 'حدّد هدفك اليومي أو احسبه من جسمك ونشاطك.')}</p>{state.profile && <div className="mt-6 flex items-center justify-between"><div><span className="text-[9px] text-[#adca9d]">{t('Current', 'الحالي')}</span><strong className="mt-1 block text-[26px] font-semibold">{state.profile.weight}<small className="ms-1 text-[10px] font-normal text-[#b7ccab]">{t('kg', 'كجم')}</small></strong></div><ArrowRight size={19} className={`text-[#81a46f] ${locale === 'ar' ? 'rotate-180' : ''}`} /><div><span className="text-[9px] text-[#adca9d]">{t('Target', 'الهدف')}</span><strong className="mt-1 block text-[26px] font-semibold">{state.profile.targetWeight}<small className="ms-1 text-[10px] font-normal text-[#b7ccab]">{t('kg', 'كجم')}</small></strong></div></div>}{plan && <p className="mt-3 flex items-center gap-1.5 text-[10px] leading-5 text-[#c0d6ac]"><CalendarDays size={13} />{plan.completed ? t('Goal reached · targets now maintain your weight', 'حققت الهدف · السعرات الآن للتثبيت') : plan.weeksToGoal ? t(`Around ${plan.weeksToGoal} weeks · an estimate`, `حوالي ${plan.weeksToGoal} أسبوع · تقدير`) : state.profile?.goal === 'maintain' ? t('Maintain and review your progress', 'تابع تقدمك وراجع خطتك') : t('Review your intake with a professional', 'راجع احتياجك مع مختص')}</p>}<button className="mt-6 flex w-full items-center justify-between rounded-lg border border-white/10 bg-white/5 px-3 py-2.5 text-[11px] font-medium text-[#daeac7] hover:bg-white/10" onClick={() => setGoalsOpen(true)}>{state.profile ? t('Review my plan', 'مراجعة خطتي') : t('Set my targets', 'تحديد أهدافي')}<ArrowRight size={15} className={locale === 'ar' ? 'rotate-180' : ''} /></button><span className="pointer-events-none absolute -end-20 top-8 h-60 w-60 rounded-full border border-white/5" /></section>
              <section className="panel p-6"><div className="mb-4 flex items-center gap-2"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-sky-50 text-sky-500 dark:bg-sky-950/35 dark:text-sky-300"><Droplets size={17} /></span><h2 className="text-[14px] font-semibold">{t('A little hydration', 'شوية ترطيب')}</h2></div><p className="text-[25px] font-semibold text-[var(--ink)]">{fmt(water)}<span className="ms-1.5 text-[10px] font-normal text-[var(--muted)]">/ {fmt(state.goals.waterMl)} {t('ml', 'مل')}</span></p><div className="my-4 flex gap-1.5" aria-label={t('Water progress', 'تقدم شرب الماء')}>{Array.from({ length: 8 }, (_, i) => <span key={i} className={`h-7 flex-1 rounded-[5px] ${water / state.goals.waterMl * 8 > i ? 'bg-sky-200 dark:bg-sky-700' : 'bg-[var(--soft)]'}`} />)}</div><p className="mb-4 text-[10px] leading-5 text-[var(--muted)]">{t('One glass at a time. Your target is adjustable.', 'كوب وراء كوب. يمكنك تعديل هدفك.')}</p><div className="flex gap-2"><button className="btn-soft flex-1 !border-0 !bg-sky-50 !text-sky-600 dark:!bg-sky-950/35 dark:!text-sky-300" disabled={water >= 10000} onClick={() => commit({ ...state, water: { ...state.water, [date]: water + 250 } })}><Plus size={14} />250 {t('ml', 'مل')}</button><button className="icon-btn border border-[var(--border)]" aria-label={t('Remove 250 ml water', 'إزالة 250 مل ماء')} disabled={water === 0} onClick={() => commit({ ...state, water: { ...state.water, [date]: Math.max(0, water - 250) } })}><ChevronLeft size={15} /></button></div></section>
              {!samplePresent && <section className="panel p-5 sm:col-span-2 xl:col-span-1"><span className="mb-3 flex h-9 w-9 items-center justify-center rounded-lg bg-[var(--soft)] text-[var(--green)]"><Sparkles size={18} /></span><h3 className="text-[13px] font-semibold">{t('Take a look around', 'جرّب الموقع')}</h3><p className="mb-4 mt-2 text-[11px] leading-5 text-[var(--muted)]">{t('Load a clearly marked sample week to explore your diary and charts.', 'حمّل أسبوعاً تجريبياً موضّحاً لاستكشاف السجلّ والرسوم.')}</p><button className="btn-soft w-full" onClick={sample}>{t('Try sample data', 'تحميل بيانات تجريبية')}<ArrowRight size={13} /></button></section>}
            </div>
          </div><div className="mt-6"><NutritionChart meals={state.meals} goals={state.goals} date={date} locale={locale} onSelectDate={setDate} /></div>
        </div>}
        {tab === 'diary' && <div className="reveal"><div className="mb-5 flex flex-wrap items-center justify-between gap-3">{dateControl}<span className="text-[11px] text-[var(--muted)]">{formatDate(date, locale)} · {dayMeals.length} {t('meals', 'وجبات')}</span></div><div className="mb-6 grid grid-cols-2 gap-3 sm:grid-cols-4">{[{ label: t('Calories', 'السعرات'), value: totals.calories, icon: Flame, unit: t('kcal', 'سعرة') }, ...nutrientCards.map(item => ({ label: item[locale], value: totals[item.key], icon: item.icon, unit: t('g', 'جم') }))].map(item => <div className="panel p-4 sm:p-5" key={item.label}><item.icon size={19} className="mb-3 text-[var(--green)]" /><span className="block text-[10px] text-[var(--muted)]">{item.label}</span><strong className="mt-1.5 block text-[24px] font-semibold">{fmt(item.value, 1)} <small className="text-[10px] font-normal text-[var(--muted)]">{item.unit}</small></strong></div>)}</div><div className="grid gap-5 lg:grid-cols-2">{mealTypes.map(mealsFor)}</div><div className="mt-6 flex items-start gap-3 rounded-xl border border-[var(--border)] bg-[var(--soft)] p-4 text-[11px] leading-6 text-[var(--muted)]"><ShieldCheck size={17} className="mt-1 text-[var(--green)]" />{t('Meals are saved on this browser only. Export your journal in Settings to keep a backup or move it to another device.', 'الوجبات محفوظة في هذا المتصفح فقط. صدّر سجلّك من الإعدادات للاحتفاظ بنسخة أو نقله لجهاز آخر.')}</div></div>}
        {tab === 'insights' && <div className="reveal space-y-6"><NutritionChart meals={state.meals} goals={state.goals} date={date} locale={locale} onSelectDate={selected => { setDate(selected); setTab('diary'); }} /><WeightChart weights={state.weights} target={state.profile?.targetWeight} locale={locale} /><section className="panel p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><h2 className="text-sm font-semibold">{t('Your weight journal', 'سجلّ الوزن')}</h2><button className="btn-soft !text-[11px]" onClick={openWeight}><Plus size={14} />{t('Add measurement', 'أضف قياساً')}</button></div>{state.weights.length ? <div>{[...state.weights].sort((a, b) => b.date.localeCompare(a.date)).map(entry => <div className="flex items-center justify-between border-b border-[var(--border)] py-3 last:border-0" key={entry.id}><span className="flex items-center gap-3 text-[11px] text-[var(--muted)]"><Scale size={16} />{formatDate(entry.date, locale)}</span><strong className="text-[15px] font-semibold">{entry.weight}<small className="ms-1 text-[10px] font-normal text-[var(--muted)]">{t('kg', 'كجم')}</small></strong></div>)}</div> : <p className="py-8 text-center text-xs text-[var(--muted)]">{t('No measurements yet. Start with where you are today.', 'لا توجد قياسات بعد. ابدأ بوزنك اليوم.')}</p>}<p className="mt-4 text-[10px] leading-5 text-[var(--muted)]">{t('Measure under similar conditions. Normal day-to-day changes can include water and food weight.', 'قِس وزنك في ظروف متشابهة. التغيّر اليومي قد يشمل وزن الماء والطعام.')}</p></section></div>}
        {tab === 'library' && <FoodLibrary locale={locale} add={() => openMeal()} />}
        {tab === 'settings' && <div className="reveal grid items-start gap-5 lg:grid-cols-2"><section className="panel p-6"><h2 className="mb-2 text-[16px] font-semibold">{t('Your daily targets', 'أهدافك اليومية')}</h2><p className="mb-5 text-xs leading-6 text-[var(--muted)]">{t('Start with sample targets, or calculate a plan using your own details.', 'ابدأ بأهداف توضيحية أو احسب خطتك باستخدام بياناتك.')}</p><dl>{[{ label: t('Calories', 'السعرات'), value: `${state.goals.calories} ${t('kcal', 'سعرة')}` }, { label: t('Protein', 'البروتين'), value: `${state.goals.protein} ${t('g', 'جم')}` }, { label: t('Carbohydrates', 'الكارب'), value: `${state.goals.carbs} ${t('g', 'جم')}` }, { label: t('Fat', 'الدهون'), value: `${state.goals.fat} ${t('g', 'جم')}` }, { label: t('Water', 'الماء'), value: `${state.goals.waterMl} ${t('ml', 'مل')}` }].map(item => <div className="flex items-center justify-between border-b border-[var(--border)] py-3 text-xs last:border-0" key={item.label}><dt className="text-[var(--muted)]">{item.label}</dt><dd className="font-medium">{item.value}</dd></div>)}</dl><button className="btn-soft mt-5 w-full" onClick={() => setGoalsOpen(true)}><Target size={15} />{t('Personalize daily targets', 'تخصيص الأهداف اليومية')}</button></section><section className="panel p-6"><h2 className="mb-5 text-[16px] font-semibold">{t('Make yourself at home', 'خلّ الموقع يناسبك')}</h2><div className="mb-5"><p className="mb-2 text-xs text-[var(--muted)]">{t('Appearance', 'المظهر')}</p><div className="flex gap-2">{(['light', 'dark'] as const).map(theme => <button key={theme} className={`btn-soft flex-1 ${state.theme === theme ? '!border-[var(--green)]' : ''}`} aria-pressed={state.theme === theme} onClick={() => commit({ ...state, theme })}>{theme === 'light' ? <Sun size={16} /> : <Moon size={16} />}{theme === 'light' ? t('Light', 'فاتح') : t('Dark', 'داكن')}</button>)}</div></div><div><p className="mb-2 text-xs text-[var(--muted)]">{t('Language', 'اللغة')}</p><div className="flex gap-2">{(['en', 'ar'] as const).map(language => <button key={language} className={`btn-soft flex-1 ${locale === language ? '!border-[var(--green)]' : ''}`} aria-pressed={locale === language} onClick={() => commit({ ...state, locale: language })}>{language === 'en' ? 'English' : 'العربية'}</button>)}</div></div><div className="mt-6 rounded-xl bg-[var(--soft)] p-4 text-[11px] leading-6 text-[var(--muted)]"><ShieldCheck size={18} className="mb-2 text-[var(--green)]" />{t('Your journal stays in this browser. Only photos you choose to analyze and their descriptions are sent to OpenAI.', 'سجلّك محفوظ في هذا المتصفح. تُرسل إلى OpenAI فقط الصور التي تختار تحليلها مع أوصافها.')}</div></section><section className="panel p-6"><h2 className="mb-2 text-[16px] font-semibold">{t('Your data, your way', 'بياناتك، بطريقتك')}</h2><p className="mb-5 text-xs leading-6 text-[var(--muted)]">{t('Clearing browser data removes your journal. Export a backup to keep it safe. Imports replace the current journal after confirmation.', 'مسح بيانات المتصفح يزيل سجلّك. صدّر نسخة للاحتفاظ به. الاستيراد يستبدل السجلّ الحالي بعد التأكيد.')}</p><input className="sr-only" ref={importRef} type="file" accept="application/json,.json" onChange={event => { void importData(event.target.files?.[0]); }} /><div className="flex flex-wrap gap-2"><button className="btn-soft" onClick={() => exportData()}><Download size={15} />{t('Export journal', 'تصدير السجلّ')}</button><button className="btn-soft" onClick={() => importRef.current?.click()}><Upload size={15} />{t('Import backup', 'استيراد نسخة')}</button></div><div className="mt-5 border-t border-[var(--border)] pt-5"><button className="flex items-center gap-2 text-xs text-red-500 dark:text-red-300" onClick={() => setConfirm({ type: 'reset' })}><Trash2 size={15} />{t('Clear all local data', 'مسح كل البيانات المحلية')}</button></div></section><section className="panel p-6"><div className="mb-3 flex items-center gap-2"><Camera size={19} className="text-[var(--green)]" /><h2 className="text-[16px] font-semibold">{t('AI photos, reviewed by you', 'صور بالذكاء الاصطناعي، بمراجعتك')}</h2></div><p className="text-xs leading-7 text-[var(--muted)]">{t('Upload a food photo with an optional description. When enabled, OpenAI estimates foods, portions, and nutrients. Review and edit the results before adding them to your meal. Manual food search is always available.', 'ارفع صورة طعام مع وصف اختياري. عند تفعيل التحليل، يقدّر OpenAI الأطعمة والكميات والقيم الغذائية. راجع النتائج وعدّلها قبل إضافتها لوجبتك. البحث اليدوي عن الأطعمة متاح دائماً.')}</p><button className="btn-soft mt-5" onClick={() => openMeal()}><Camera size={15} />{t('Add a meal with a photo', 'أضف وجبة مع صورة')}</button></section><section className="panel p-6 lg:col-span-2"><div className="flex items-start gap-3"><Info size={20} className="mt-1 text-[var(--green)]" /><div><h2 className="mb-2 text-sm font-semibold">{t('A useful starting point', 'بداية مفيدة')}</h2><p className="text-xs leading-7 text-[var(--muted)]">{t('Local food values are representative estimates per 100 g, not a verified nutrition label. Cooking methods and portions change the result. Default targets are examples, not a recommendation. The optional calculator uses Mifflin–St Jeor for adults; estimates are not medical advice.', 'قيم الأطعمة المحلية تقديرات تمثيلية لكل 100 جم وليست بديلاً عن الملصق الغذائي. الطبخ والحصص تغيّر النتيجة. الأهداف الافتراضية أمثلة وليست توصية. الحاسبة الاختيارية تستخدم معادلة Mifflin–St Jeor للبالغين، والتقديرات ليست نصيحة طبية.')}</p></div></div><button className="btn-soft mt-5" onClick={sample}><Sparkles size={15} />{t('Load sample week', 'تحميل أسبوع تجريبي')}</button></section></div>}
        <footer className="mt-8 flex flex-wrap items-center justify-between gap-3 border-t border-[var(--border)] pb-2 pt-5 text-[9px] text-[var(--muted)]"><span className="flex items-center gap-1.5"><Leaf size={13} />{t('A7sbha · A little balance, every day.', 'أحسبها · توازن صغير، كل يوم.')}</span><button className="flex items-center gap-1.5 hover:text-[var(--green)]" onClick={() => setHelpOpen(true)}>{t('About your nutrition estimates', 'عن تقديرات التغذية')}<CircleHelp size={12} /></button></footer>
      </main>
    </div>
    <nav className="fixed inset-x-0 bottom-0 z-40 flex h-[68px] items-center justify-around border-t border-[var(--border)] bg-[var(--surface)] px-2 pb-[env(safe-area-inset-bottom)] lg:hidden" aria-label={t('Mobile navigation', 'قائمة الهاتف')}>{tabs.map(item => <button key={item.id} aria-current={tab === item.id ? 'page' : undefined} onClick={() => setTab(item.id)} className={`flex min-w-[55px] flex-col items-center gap-1.5 rounded-lg px-2 py-2.5 text-[9px] ${tab === item.id ? 'bg-[var(--soft)] font-medium text-[var(--green)]' : 'text-[var(--muted)]'}`}><item.icon size={18} />{item.id === 'dashboard' ? t('Home', 'الرئيسية') : item.id === 'diary' ? t('Diary', 'وجباتي') : item.id === 'insights' ? t('Progress', 'تقدّمي') : item.id === 'library' ? t('Foods', 'الأطعمة') : t('Settings', 'إعداداتي')}</button>)}</nav>
    {toast && <div className="fixed bottom-20 left-1/2 z-[100] flex w-max max-w-[calc(100vw-32px)] -translate-x-1/2 items-center gap-2.5 rounded-xl border border-[#477d56] bg-[#234d37] px-4 py-3 text-xs leading-5 text-[#edf4e8] shadow-xl lg:bottom-6" role="status"><Check size={16} className="text-[#bfd998]" /><span>{toast}</span><button className="ms-2" onClick={() => setToast('')} aria-label={t('Dismiss notification', 'إغلاق التنبيه')}><X size={15} /></button></div>}
    {editor && <MealEditor locale={locale} date={date} initialType={editor.type} editing={editor.meal} onClose={() => setEditor(null)} onSave={saveMeal} />}
    {goalsOpen && <GoalsDialog locale={locale} profile={state.profile} goals={state.goals} onClose={() => setGoalsOpen(false)} onSave={saveGoals} />}
    {confirm && <SimpleDialog title={confirm.type === 'delete' ? t('Remove this meal?', 'حذف هذه الوجبة؟') : confirm.type === 'reset' ? t('Clear your local journal?', 'مسح سجلّك المحلي؟') : t('Replace your current journal?', 'استبدال سجلّك الحالي؟')} close={() => setConfirm(null)} closeLabel={t('Close', 'إغلاق')}><p className="text-xs leading-7 text-[var(--muted)]">{confirm.type === 'delete' ? t('This meal will be removed and your daily totals will update.', 'ستُحذف الوجبة وتتحدّث مجاميع يومك.') : confirm.type === 'reset' ? t('This removes all meals, photos, measurements, and targets from this browser. Export a backup first if you want to keep them.', 'سيزيل هذا كل الوجبات والصور والقياسات والأهداف من هذا المتصفح. صدّر نسخة أولاً إذا أردت الاحتفاظ بها.') : t('The imported backup will replace the meals and settings on this browser. You can export your current journal before continuing.', 'ستستبدل النسخة المستوردة الوجبات والإعدادات في هذا المتصفح. يمكنك تصدير سجلّك الحالي قبل المتابعة.')}</p><div className="mt-5 flex flex-wrap gap-3"><button className="btn" onClick={confirmAction}>{confirm.type === 'delete' ? t('Remove meal', 'حذف الوجبة') : confirm.type === 'reset' ? t('Clear journal', 'مسح السجلّ') : t('Import and replace', 'استيراد واستبدال')}</button><button className="btn-soft" onClick={() => setConfirm(null)}>{t('Cancel', 'إلغاء')}</button>{confirm.type !== 'delete' && <button className="btn-soft" onClick={() => exportData()}><Download size={14} />{t('Export first', 'تصدير أولاً')}</button>}</div></SimpleDialog>}
    {weightOpen && <SimpleDialog title={t('A new check-in', 'قياس جديد')} close={() => setWeightOpen(false)} closeLabel={t('Close', 'إغلاق')}><form className="space-y-5" onSubmit={logWeight}><p className="text-xs leading-6 text-[var(--muted)]">{t('Log your weight. If you have a calculated plan, we’ll refresh its targets.', 'سجّل وزنك. إذا كانت لديك خطة محسوبة سنحدّث أهدافها.')}</p><label className="block text-xs font-medium">{t('Weight (kg)', 'الوزن (كجم)')}<input className={`${fieldClass} mt-2`} type="number" min="30" max="350" step="0.1" value={weightValue} onChange={event => setWeightValue(event.target.value)} required /></label><label className="block text-xs font-medium">{t('Measurement date', 'تاريخ القياس')}<input className={`${fieldClass} mt-2`} type="date" max={dateKey()} value={weightDate} onChange={event => setWeightDate(event.target.value)} required /></label>{weightError && <p className="text-xs text-red-500" role="alert">{weightError}</p>}<button className="btn w-full"><Check size={15} />{t('Save measurement', 'حفظ القياس')}</button></form></SimpleDialog>}
    {helpOpen && <SimpleDialog title={t('Nutrition, without the mystery', 'التغذية، بكل وضوح')} close={() => setHelpOpen(false)} closeLabel={t('Close', 'إغلاق')}><div className="space-y-4 text-xs leading-7 text-[var(--muted)]"><p>{t('Search a food, choose its weight in grams, and add it to breakfast, lunch, dinner, or snacks. We scale the local per-100-g nutrition values to your portion and total your day.', 'ابحث عن الطعام وحدّد وزنه بالجرام، ثم أضفه للفطور أو الغداء أو العشاء أو السناك. نُعدّل القيم لكل 100 جم حسب حصتك ونجمع يومك.')}</p><p>{t('The database contains sample reference foods in Arabic and English. Values are estimates; labels and recipes may differ.', 'القاعدة تحتوي أطعمة مرجعية نموذجية بالعربية والإنجليزية. القيم تقديرية وقد تختلف الملصقات والوصفات.')}</p><p>{t('Your journal is stored in this browser. Export a backup before clearing browser data. Optional photo analysis sends only your chosen photo and description to OpenAI, through the app server.', 'سجلّك محفوظ في هذا المتصفح. صدّر نسخة قبل مسح بيانات المتصفح. يرسل تحليل الصور الاختياري صورتك المختارة ووصفها فقط إلى OpenAI عبر خادم التطبيق.')}</p><p>{t('Photo analysis estimates food identity, weight, and nutrition; it cannot measure a portion precisely. Review every suggestion before adding it. You can always use the local food database instead.', 'يقدّر تحليل الصور نوع الطعام ووزنه وتغذيته، ولا يقيس الحصة بدقة. راجع كل اقتراح قبل إضافته. يمكنك استخدام قاعدة الأطعمة المحلية دائماً.')}</p><button className="btn mt-2 w-full" onClick={() => setHelpOpen(false)}>{t('Got it, let’s go', 'واضح، نكمّل')}</button></div></SimpleDialog>}
  </div>;
}

function MealRow({ meal, locale, onEdit, onDelete }: { meal: Meal; locale: Locale; onEdit: () => void; onDelete: () => void }) {
  const total = mealNutrients(meal); const t = (en: string, ar: string) => text(locale, en, ar);
  return <article className="border-b border-[var(--border)] py-4 last:border-0"><div className="flex items-start gap-3">{meal.photo ? <img src={meal.photo} alt={t('Attached meal photo', 'صورة الوجبة المرفقة')} className="h-11 w-11 shrink-0 rounded-lg object-cover" /> : <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-[var(--soft)] text-[23px]">{(meal.items[0] ? getMealItemFood(meal.items[0])?.emoji : undefined) || mealNames[meal.type].emoji}</span>}<div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-1.5"><h4 className="truncate text-xs font-semibold">{meal.name || mealNames[meal.type][locale]}</h4>{meal.items.some(item => item.estimatedFood) && <span className="rounded bg-[var(--soft)] px-1.5 py-0.5 text-[8px] font-medium text-[var(--green)]">{t('AI estimate', 'تقدير بالذكاء الاصطناعي')}</span>}{meal.id.startsWith('demo-') && <span className="rounded bg-[var(--soft)] px-1.5 py-0.5 text-[8px] font-medium text-[var(--green)]">{t('SAMPLE', 'تجريبي')}</span>}</div><p className="mt-1 text-[10px] leading-5 text-[var(--muted)]">{meal.items.map(item => { const food = getMealItemFood(item); return `${food ? locale === 'ar' ? food.nameAr : food.name : item.foodId} ${fmt(item.grams)}${t('g', 'جم')}`; }).join(' · ')}</p></div><div className="shrink-0 text-end"><strong className="block text-[14px] font-semibold text-[var(--green)]">{fmt(total.calories)}</strong><small className="text-[9px] text-[var(--muted)]">{t('kcal', 'سعرة')}</small></div></div><div className="mt-2.5 flex items-center justify-between gap-2"><p className="text-[9px] text-[var(--muted)]">{t('P', 'بروتين')} {fmt(total.protein, 1)} · {t('C', 'كارب')} {fmt(total.carbs, 1)} · {t('F', 'دهون')} {fmt(total.fat, 1)} {t('g', 'جم')}</p><div className="flex"><button className="icon-btn !h-6 !w-6" aria-label={`${t('Edit meal', 'تعديل الوجبة')}: ${meal.name}`} onClick={onEdit}><Pencil size={12} /></button><button className="icon-btn !h-6 !w-6 hover:!text-red-400" aria-label={`${t('Delete meal', 'حذف الوجبة')}: ${meal.name}`} onClick={onDelete}><Trash2 size={12} /></button></div></div></article>;
}

function FoodLibrary({ locale, add }: { locale: Locale; add: () => void }) {
  const [query, setQuery] = useState(''); const [category, setCategory] = useState<Food['category'] | 'all'>('all');
  const t = (en: string, ar: string) => text(locale, en, ar); const results = searchFoods(query, category);
  const categories = [{ id: 'all', en: 'All foods', ar: 'كل الأطعمة' }, { id: 'protein', en: 'Protein', ar: 'بروتين' }, { id: 'grains', en: 'Grains', ar: 'حبوب' }, { id: 'fruit', en: 'Fruit', ar: 'فواكه' }, { id: 'vegetables', en: 'Vegetables', ar: 'خضار' }, { id: 'dairy', en: 'Dairy', ar: 'ألبان' }, { id: 'fats', en: 'Fats', ar: 'دهون' }, { id: 'dishes', en: 'Dishes', ar: 'أطباق' }];
  return <div className="reveal"><div className="mb-4 flex items-center gap-3 rounded-xl border border-[var(--border)] bg-[var(--surface)] px-4 py-3.5"><Search size={18} className="text-[var(--muted)]" /><input type="search" value={query} onChange={event => setQuery(event.target.value)} aria-label={t('Search food library', 'البحث في دليل الأطعمة')} placeholder={t('Search chicken, rice, دجاج, أرز…', 'ابحث عن دجاج، أرز، chicken، rice…')} className="w-full bg-transparent text-sm" /><span className="shrink-0 rounded-md bg-[var(--soft)] px-2 py-1 text-[9px] text-[var(--muted)]">{foods.length} {t('foods', 'طعاماً')}</span></div><div className="tab-scroll mb-5 flex gap-2">{categories.map(item => <button key={item.id} className={`shrink-0 rounded-full border px-3.5 py-2 text-[11px] ${category === item.id ? 'border-[var(--green)] bg-[var(--soft)] text-[var(--green)]' : 'border-[var(--border)] bg-[var(--surface)] text-[var(--muted)]'}`} onClick={() => setCategory(item.id as typeof category)} aria-pressed={category === item.id}>{item[locale]}</button>)}</div><p className="mb-5 text-[10px] text-[var(--muted)]">{results.length} {t('results · Representative sample values per 100 g.', 'نتائج · قيم نموذجية لكل 100 جم.')}</p>{results.length ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{results.map(food => <article className="panel p-5" key={food.id}><div className="mb-4 flex items-center gap-3"><span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-[var(--soft)] text-[27px]">{food.emoji}</span><div className="min-w-0"><h3 className="text-xs font-semibold">{locale === 'ar' ? food.nameAr : food.name}</h3><p className="mt-1 text-[10px] text-[var(--muted)]" dir={locale === 'ar' ? 'ltr' : 'rtl'}>{locale === 'ar' ? food.name : food.nameAr}</p></div></div><div className="flex items-center justify-between border-t border-[var(--border)] pt-4"><strong className="text-xl font-semibold text-[var(--green)]">{food.per100g.calories}<small className="ms-1 text-[9px] font-normal text-[var(--muted)]">{t('kcal / 100 g', 'سعرة / 100 جم')}</small></strong><span className="text-[9px] text-[var(--muted)]">{t('P', 'ب')} {food.per100g.protein} · {t('C', 'ك')} {food.per100g.carbs} · {t('F', 'د')} {food.per100g.fat}</span></div><p className="mt-3 text-[9px] text-[var(--muted)]">{t('Typical portion', 'حصة تقريبية')}: {food.servingGrams}{t('g', 'جم')} · {locale === 'ar' ? food.servingLabelAr : food.servingLabel}</p></article>)}</div> : <div className="panel flex flex-col items-center py-16 text-center"><Search size={30} className="mb-4 text-[var(--green)]" /><h3 className="text-sm font-medium">{t('No matching foods', 'لا توجد أطعمة مطابقة')}</h3><p className="mt-2 text-xs text-[var(--muted)]">{t('Try another Arabic or English name, or choose another category.', 'جرّب اسماً عربياً أو إنجليزياً آخر أو غيّر الفئة.')}</p><button className="btn-soft mt-5" onClick={() => { setQuery(''); setCategory('all'); }}>{t('Reset search', 'إعادة ضبط البحث')}</button></div>}</div>;
}

function SimpleDialog({ title, children, close, closeLabel }: { title: string; children: React.ReactNode; close: () => void; closeLabel: string }) {
  const ref = useRef<HTMLElement>(null);
  const closeRef = useRef(close);
  closeRef.current = close;
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null; const old = document.body.style.overflow; document.body.style.overflow = 'hidden';
    const elements = () => [...(ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),a[href]') || [])].filter(element => element.offsetParent !== null);
    (ref.current?.querySelector<HTMLInputElement>('input') || elements()[0])?.focus();
    function key(event: KeyboardEvent) { if (event.key === 'Escape') closeRef.current(); if (event.key !== 'Tab') return; const list = elements(); if (!list.length) { event.preventDefault(); return; } if (event.shiftKey && (document.activeElement === list[0] || !ref.current?.contains(document.activeElement))) { event.preventDefault(); list.at(-1)?.focus(); } else if (!event.shiftKey && (document.activeElement === list.at(-1) || !ref.current?.contains(document.activeElement))) { event.preventDefault(); list[0].focus(); } }
    document.addEventListener('keydown', key); return () => { document.removeEventListener('keydown', key); document.body.style.overflow = old; previous?.isConnected && previous.focus(); };
  }, []);
  return <div className="fixed inset-0 z-[80] flex items-center justify-center overflow-y-auto bg-[#122c20]/50 p-4 backdrop-blur-sm" onMouseDown={event => { if (event.currentTarget === event.target) close(); }}><section ref={ref} role="dialog" aria-modal="true" aria-label={title} className="panel max-h-[calc(100dvh-32px)] w-full max-w-[460px] overflow-y-auto p-6 shadow-2xl"><div className="mb-5 flex items-center justify-between gap-3"><h2 className="text-lg font-semibold">{title}</h2><button className="icon-btn" aria-label={closeLabel} onClick={close}><X size={20} /></button></div>{children}</section></div>;
}
